          bleed: "off",
          caption: {
            en: "<b>Ein Herz fürs Eistauchen!</b>",
          },
          role: "photo",
          width: 1129,
          credit: "",
          linktype: "none",
          alt: "",
          rawimage: "off",
          externallinktarget: "on",
