                imagelink: "",
                text_lang: {
                  en: "<p>Im Gegensatz zu normalen Tauchgängen muss beim Eistauchen jederzeit ein aufmerksamer Helfer bereitstehen. Der Einstieg ins Wasser erfolgt nacheinander.</p>",
                },
